const s=$input.first().json;
if(s.results.length!==s.cases.length) throw new Error('SYNTHESIS_ADVERSARIAL_COUNT_MISMATCH');
const failed=s.results.filter(x=>!x.passed);
s.summary={total:s.cases.length,passed:s.cases.length-failed.length,failed:failed.length,status:failed.length?'FAILED':'PASSED'};
if(failed.length) throw new Error('SYNTHESIS_ADVERSARIAL_FAILURE:'+failed.map(x=>x.id).join(','));
return [{json:s}];

const s=$input.first().json;
